mapper.select:
select * from crm_followup_rule_enrollment
where tenant_id = #{tenantId} and idempotency_key = #{idempotencyKey}
limit 1

select enrollment_id, rule_id, trigger_type, subject_type, subject_id, status,
       next_run_at, task_id, skip_reason, cancel_reason, retry_count, fired_time, create_time
from crm_followup_rule_enrollment
where tenant_id = #{tenantId}

    and rule_id = #{ruleId}


    and status = #{status}


    and subject_id = #{subjectId}

order by create_time desc

select count(1) from crm_followup_rule_enrollment
where tenant_id = #{tenantId}
  and rule_id = #{ruleId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'fired'

select count(1) from crm_followup_rule_enrollment
where tenant_id = #{tenantId}
  and rule_id = #{ruleId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'fired'
  and fired_time >= #{since}

select * from crm_followup_rule_enrollment
where tenant_id = #{tenantId}
  and rule_id = #{ruleId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'pending'
order by next_run_at asc
limit 1

select * from crm_followup_rule_enrollment
where tenant_id = #{tenantId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'pending'

    and trigger_type = #{triggerType}

select * from crm_followup_rule_enrollment
where tenant_id = #{tenantId}
  and status = 'pending'
  and next_run_at <= #{now}
  and retry_count < #{maxRetry}
order by next_run_at asc
limit #{limit}
for update skip locked

mapper.update:
update crm_followup_rule_enrollment
set status = 'cancelled',
    cancel_reason = #{cancelReason},
    update_time = now()
where tenant_id = #{tenantId}
  and subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and status = 'pending'

    and trigger_type = #{triggerType}
